import glob
import os

import matplotlib.pyplot as plt
import numpy as np
import torch
import torch.nn.functional as F
from scipy.stats import pearsonr

# %% ../nbs/16_ssm_analysis.ipynb #d4e5f6a7
def load_songs_all_levels(encoded_dir, song_indices, split='train'):
    """Single-pass load of all 6 encoder levels + images for a set of songs.

    Patch embeddings are flattened (not mean-pooled) to preserve spatial structure.
    Returns dict keyed by song_idx, each value:
        {'embs': {level: Tensor[N_crops, N_patches*D]}, 'imgs': Tensor[N_crops, 1, H, W]}
    """
    encoded_dir = os.path.expanduser(encoded_dir)
    files = sorted(glob.glob(os.path.join(encoded_dir, f'{split}_chunk*.pt')))
    assert files, f"No {split}_chunk*.pt found in {encoded_dir}"

    song_set = set(song_indices)
    acc = {s: {'embs': {l: [] for l in range(6)}, 'imgs': []} for s in song_set}

    for fi, f in enumerate(files):
        print(f"  chunk {fi+1}/{len(files)}\r", end='', flush=True)
        data = torch.load(f, map_location='cpu', weights_only=False)
        for item in data:
            file_idxs = item['file_idx']
            for s in song_set:
                mask = (file_idxs == s)
                if not mask.any():
                    continue
                for lvl in range(6):
                    emb = item['emb1'][lvl].float()            # [B, N_patches, D]
                    acc[s]['embs'][lvl].append(emb[mask].flatten(1))  # flatten → [n, N_patches*D]
                acc[s]['imgs'].append(item['img1'].float()[mask])
    print()

    result = {}
    for s in song_indices:
        embs = {lvl: (torch.cat(acc[s]['embs'][lvl], dim=0) if acc[s]['embs'][lvl] else None)
                for lvl in range(6)}
        imgs = torch.cat(acc[s]['imgs'], dim=0) if acc[s]['imgs'] else None
        result[s] = {'embs': embs, 'imgs': imgs}
    return result

# %% ../nbs/16_ssm_analysis.ipynb #e5f6a7b8
def compute_ssm(vecs):
    "Pairwise cosine similarity matrix. vecs: [N, D] -> [N, N] numpy array."
    normed = F.normalize(vecs, dim=-1)
    return (normed @ normed.T).numpy()


def compute_pixel_ssm(imgs):
    "Pixel-space SSM: flatten each image, cosine similarity. imgs: [N, 1, H, W]."
    flat = imgs.flatten(1).float()
    return compute_ssm(flat)

# %% ../nbs/16_ssm_analysis.ipynb #f6a7b8c9
def plot_ssm_alllevels(song_data, song_idx, out_dir=None, show=True):
    """Plot SSM for all 6 encoder levels + pixel space for a single song.

    song_data: dict from load_songs_all_levels, keyed by song_idx.
    Returns (ssms dict, pearson_rs dict) keyed by level (0-5) and 'pixel'.
    """
    imgs = song_data['imgs']
    if imgs is None:
        print(f"Song {song_idx} not found.")
        return None, None
    pixel_ssm = compute_pixel_ssm(imgs)

    fig, axes = plt.subplots(2, 4, figsize=(18, 9))
    fig.suptitle(f"SSM -- Song {song_idx:03d} ({len(imgs)} crops)", fontsize=14)

    ax = axes[1, 3]
    ax.imshow(pixel_ssm, cmap='viridis', vmin=-1, vmax=1, aspect='auto')
    ax.set_title("Pixel space")
    ax.set_xlabel('Crop'); ax.set_ylabel('Crop')

    ssms = {'pixel': pixel_ssm}
    pearson_rs = {}

    for lvl in range(6):
        row, col = divmod(lvl, 4)
        ax = axes[row, col]
        embs = song_data['embs'][lvl]
        if embs is None:
            ax.set_title(f"L{lvl} -- no data")
            continue
        ssm = compute_ssm(embs)
        ssms[lvl] = ssm
        r, _ = pearsonr(ssm.flatten(), pixel_ssm.flatten())
        pearson_rs[lvl] = r
        ax.imshow(ssm, cmap='viridis', vmin=-1, vmax=1, aspect='auto')
        ax.set_title(f"L{lvl} ({embs.shape[1]}d)  r={r:.3f}")
        ax.set_xlabel('Crop'); ax.set_ylabel('Crop')

    plt.tight_layout()
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
        path = os.path.join(out_dir, f"ssm_song{song_idx:03d}.png")
        plt.savefig(path, dpi=150)
        print(f"Saved: {path}")
    if show:
        plt.show()
    else:
        plt.close()

    return ssms, pearson_rs

# %% ../nbs/16_ssm_analysis.ipynb #a7b8c9d0
def ssm_survey(encoded_dir, song_indices, split='train', out_dir='./results/ssm'):
    """Run SSM analysis over multiple songs, collect Pearson r values per level.

    Does a single pass over all chunks to load all songs at all levels,
    then computes SSMs. Returns {level: [r_song1, r_song2, ...]} for levels 0-5.
    """
    print(f"Loading {len(song_indices)} songs (single pass over chunks)...")
    all_data = load_songs_all_levels(encoded_dir, song_indices, split=split)

    all_rs = {lvl: [] for lvl in range(6)}
    for song_idx in song_indices:
        print(f"Song {song_idx:03d}...", end=' ', flush=True)
        _, rs = plot_ssm_alllevels(all_data[song_idx], song_idx, out_dir=out_dir, show=False)
        if rs is None:
            print("skipped")
            continue
        for lvl, r in rs.items():
            all_rs[lvl].append(r)
        print(" ".join(f"L{l}={rs.get(l, float('nan')):.3f}" for l in range(6)))

    print("\n--- Mean Pearson r (embedding SSM vs pixel SSM) ---")
    for lvl in range(6):
        vals = all_rs[lvl]
        if vals:
            print(f"  L{lvl}: {np.mean(vals):.3f} +/- {np.std(vals):.3f} (n={len(vals)})")
    return all_rs

